base_css:
@font-face{font-family:"Archivo";font-style:normal;font-display:swap;font-weight:100 900;font-stretch:62% 125%;src:url(/assets/fonts/archivo-var-v1.woff2) format("woff2")}
@font-face{font-family:"APW Head Fallback";src:local("Arial Bold"),local("Arial-BoldMT"),local("Arial");size-adjust:74%;ascent-override:118%;descent-override:26%;line-gap-override:0%}
:root{--f-text:"Archivo",ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;--f-head:"Archivo","APW Head Fallback","Arial Narrow",Arial,sans-serif}
body{margin:0;background:#070B1B}
*{box-sizing:border-box}
.apw{--bg:#FFFFFF;--bg2:#F6F4EF;--bg3:#E4EEF8;--card:#FFFFFF;--ink:#0E1430;--ink2:#3E4668;--mute:#4A5272;--line:#E2DDD2;--line2:#B9BED3;--field:#8A91B0;--accent:#FF4A1C;--accent-hi:#FF6B42;--accent-ink:#0E1430;--accent-text:#B02A08;--accent-soft:#FFE1D6;--ok:#1E7A52;--ok-soft:#E3F1EA;--band:#0A0F24;--band2:#111936;--shadow:0 14px 34px rgba(10,15,36,.14);font-family:var(--f-text);font-stretch:104%;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
.apw.dark{--bg:#0A0F24;--bg2:#0E1530;--bg3:#101A38;--card:#141D3D;--ink:#F6F4EF;--ink2:#D5DAF0;--mute:#AEB5D8;--line:rgba(255,255,255,.14);--line2:rgba(255,255,255,.3);--field:#6B7398;--accent-text:#FF8A66;--accent-soft:rgba(255,74,28,.16);--ok:#4CC38A;--ok-soft:rgba(76,195,138,.15);--band:#070B1B;--band2:#111936;--shadow:0 18px 40px rgba(0,0,0,.5)}
.apw a{color:var(--accent-text)}.mono{font-family:var(--f-text);font-stretch:104%;font-variant-numeric:tabular-nums}.wm{font-family:var(--f-head);font-weight:800;text-transform:uppercase;letter-spacing:.045em;line-height:1}.eb{margin:0;font-size:15px;font-weight:700;line-height:1.4;color:var(--mute)}.h1{margin:0;font-family:var(--f-head);font-stretch:68%;font-weight:850;letter-spacing:-.006em;line-height:.92;text-wrap:balance}.h2{margin:0;font-family:var(--f-head);font-stretch:68%;font-weight:850;font-size:clamp(40px,11vw,50px);letter-spacing:-.006em;line-height:.96;text-wrap:balance}.lead{margin:14px 0 0;font-size:18px;line-height:1.55;color:var(--ink2)}.nb{white-space:nowrap}.btn{display:flex;align-items:center;justify-content:center;gap:10px;min-height:58px;padding:0 26px;border-radius:12px;border:2px solid transparent;font-family:var(--f-head);font-stretch:88%;font-size:20px;font-weight:750;letter-spacing:.004em;line-height:1;cursor:pointer;text-decoration:none;white-space:nowrap}.btn:disabled{opacity:.45;cursor:not-allowed}.btn:not(:disabled):active{transform:translateY(1px)}.apw .btn-dot{background:var(--accent);color:var(--accent-ink)}.apw .btn-dot:not(:disabled):hover{background:var(--accent-hi);color:var(--accent-ink)}.apw .btn-ink{background:var(--ink);color:var(--bg)}.apw .btn-line{background:transparent;color:var(--ink);border-color:var(--line2)}.apw .btn-line:hover{border-color:var(--ink)}.apw .btn-line-n{background:transparent;color:#FFFFFF;border-color:rgba(255,255,255,.34)}.apw .btn-line-n:hover{border-color:#FFFFFF}.apw .btn-pay{background:#000000;color:#FFFFFF;border-color:#000000}.apw.dark .btn-pay{border-color:rgba(255,255,255,.4)}.ibtn{width:48px;height:48px;flex:0 0 48px;display:grid;place-items:center;border-radius:12px;border:2px solid var(--line2);background:transparent;color:var(--ink);cursor:pointer;padding:0;text-decoration:none}.apw .ibtn-n{border-color:rgba(255,255,255,.3);color:#F6F4EF}.ldot{display:inline-block;width:9px;height:9px;flex:0 0 9px;border-radius:50%;background:#FF4A1C}details>summary{list-style:none;cursor:pointer}details>summary::-webkit-details-marker{display:none}.chev{transition:transform .2s ease}details[open]>summary .chev{transform:rotate(45deg)}input:focus-visible,button:focus-visible,a:focus-visible,summary:focus-visible,textarea:focus-visible,ul:focus-visible{outline:3px solid #FF6B42;outline-offset:2px}.apw .btn-dot:focus-visible{outline-color:#F6F4EF}@media (prefers-reduced-motion:reduce){.chev{transition:none}}

svcmap.css:
.map svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.mland{fill:#F3E7D2}.dark .mland{fill:#141D3D}
.mmtn{fill:#D3C1AD}.dark .mmtn{fill:#2D2A4A}
.mridge{fill:none;stroke:#B39E88;stroke-width:1.3;stroke-linecap:round;stroke-linejoin:round}.dark .mridge{stroke:#463F6B}
.mbase{fill:#E4DCCD}.dark .mbase{fill:#1B2449}
.mrun{fill:none;stroke:#CFC5B4;stroke-width:4;stroke-linecap:round}.dark .mrun{stroke:#2C3767}
.mart{fill:none;stroke:#FFFFFF;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.dark .mart{stroke:#28346A}
.mcanal{fill:none;stroke:#8CC4E6;stroke-width:1.4;stroke-linejoin:round}.dark .mcanal{stroke:#3D6E95}
.mriver{fill:none;stroke:#8DBEE0;stroke-width:1.6;stroke-linecap:round;opacity:.7}
.mzipf{fill:rgba(255,74,28,.07);pointer-events:none}.dark .mzipf{fill:rgba(255,74,28,.10)}
.mzipl{fill:none;stroke:#FF4A1C;stroke-width:1;stroke-linejoin:round;opacity:.45;pointer-events:none}
.mzipt{font-family:Archivo,"Arial Narrow",Arial,sans-serif;font-stretch:82%;font-size:10px;font-weight:600;letter-spacing:.04em;fill:#B02A08;paint-order:stroke;stroke:#F3E7D2;stroke-width:3px;stroke-linejoin:round;pointer-events:none}.dark .mzipt{fill:#FF8A66;stroke:#141D3D}
.mplc{cursor:pointer;transition:fill .25s ease}
.mfwy0{fill:none;stroke:#D99A3A;stroke-width:6;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.mfwy{fill:none;stroke:#F7C66A;stroke-width:3.8;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.dark .mfwy0{stroke:#7A5A26}.dark .mfwy{stroke:#B98B3E}
.mnolook,.mtxt,.mplace,.mattr,.mtruck{pointer-events:none}
.mtxt{font-family:Archivo,"Arial Narrow",Arial,sans-serif;font-stretch:82%;font-size:10px;font-weight:600;letter-spacing:.06em;fill:#7A6F60}.dark .mtxt{fill:#9AA2C8}
.mtxtm{fill:#5E5045}.dark .mtxtm{fill:#C9CEE6}
.mplace{font-family:Archivo,"Arial Black",sans-serif;font-size:11.5px;font-weight:800;letter-spacing:.05em;fill:#0E1430;paint-order:stroke;stroke:#F3E7D2;stroke-width:3.2px;stroke-linejoin:round}
.dark .mplace{fill:#FFFFFF;stroke:#141D3D}
.mshield{font-family:Archivo,"Arial Narrow",Arial,sans-serif;font-stretch:82%;font-size:10px;font-weight:600}
.mattr{font-family:Archivo,"Arial Narrow",Arial,sans-serif;font-stretch:82%;font-size:8px;fill:#8A7F70}.dark .mattr{fill:#7F88B0}
.mtruck{animation:mapDrive 9s ease-in-out infinite}
@keyframes mapDrive{0%{transform:translate(133px,229px)}32%{transform:translate(193px,229px)}73%{transform:translate(193px,153px)}92%,100%{transform:translate(241px,153px)}}
.mchips{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}
.mchip{display:inline-flex;align-items:center;gap:8px;min-height:44px;padding:0 15px 0 12px;border-radius:999px;border:1.6px solid var(--ink);font:inherit;font-size:15px;font-weight:700;cursor:pointer;text-decoration:none;white-space:nowrap}
.mchip i{display:block;width:12px;height:12px;border-radius:4px;border:2px solid #FF4A1C}
.mkey{display:flex;align-items:center;gap:10px;margin:12px 0 0;font-size:15px;line-height:1.45;color:var(--ink2)}
.mkey-sw{flex:0 0 16px;width:16px;height:16px;border-radius:5px;background:#FF4A1C}
.msn{font-family:Archivo,"Arial Black",sans-serif;font-size:10px;font-weight:800;letter-spacing:.06em;fill:#4A5272;paint-order:stroke;stroke:#F3E7D2;stroke-width:3px;stroke-linejoin:round;pointer-events:none}
.dark .msn{fill:#AEB5D8;stroke:#141D3D}
.mst{font-family:Archivo,"Arial Narrow",Arial,sans-serif;font-stretch:82%;font-size:7.5px;font-weight:600;letter-spacing:.1em;fill:#B02A08;paint-order:stroke;stroke:#F3E7D2;stroke-width:2.6px;stroke-linejoin:round;pointer-events:none}
.dark .mst{fill:#FF8A66;stroke:#141D3D}
@media (prefers-reduced-motion:reduce){.mtruck{animation:none;transform:translate(193px,190px)}.mplc{transition:none}}.mlink{fill:rgba(255,74,28,0);transition:fill .2s ease}a:hover .mlink,a:focus-visible .mlink{fill:rgba(255,74,28,.24)}a:focus-visible .mlink{stroke:#0E1430;stroke-width:2.5px}.dark a:focus-visible .mlink{stroke:#FFFFFF}
